import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.2Gs1zKBA.js";const g=JSON.parse('{"title":"状态、异常与停止","description":"","frontmatter":{},"headers":[],"relativePath":"safety/index.md","filePath":"safety/index.md","lastUpdated":1794555138000}'),c={name:"safety/index.md"};function a(i,d,n,l,s,h){return t(),o("div",null,[...d[0]||(d[0]=[r(`<h1 id="状态、异常与停止" tabindex="-1">状态、异常与停止 <a class="header-anchor" href="#状态、异常与停止" aria-label="Permalink to &quot;状态、异常与停止&quot;">​</a></h1><p>安全处理的优先级是：先让机械臂停止继续运动，再确认机械支撑和供电状态，最后分析异常原因。不要在机械臂仍可能运动时先关闭通信或删除错误日志。</p><h2 id="读取状态" tabindex="-1">读取状态 <a class="header-anchor" href="#读取状态" aria-label="Permalink to &quot;读取状态&quot;">​</a></h2><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">state </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> arm.state</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(state.joints)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(state.velocities)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(state.torques)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>状态读取可用于确认目标是否被接受、运动是否仍在进行以及异常前后的反馈变化。记录状态时建议同时保存时间戳、模型、通道和当前工具/负载配置，便于复现问题。</p><h2 id="异常处理" tabindex="-1">异常处理 <a class="header-anchor" href="#异常处理" aria-label="Permalink to &quot;异常处理&quot;">​</a></h2><p>以下内容按当前 <code>onero-sdk</code> 源码整理。异常名称、字段和交付方式都是 API 合约的一部分；不要根据异常类的名称推断实际行为。</p><div class="warning custom-block"><p class="custom-block-title">真机安全</p><p>捕获异常不等于机械臂已经安全停止。人员进入工作区、机械臂卡滞、碰撞或负载可能下落时，应使用现场急停或切断 DC 48 V 供电。收到错误后不要立即重发目标或自动重新使能。</p></div><h3 id="异常的三种交付方式" tabindex="-1">异常的三种交付方式 <a class="header-anchor" href="#异常的三种交付方式" aria-label="Permalink to &quot;异常的三种交付方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>交付方式</th><th>典型场景</th><th>调用方如何处理</th></tr></thead><tbody><tr><td>接口直接 <code>raise</code></td><td>初始化失败、使能前已存在电机故障、参数错误、逆解失败</td><td>在调用接口的 <code>try/except</code> 中捕获</td></tr><tr><td><code>Arm(..., on_error=callback)</code> 回调</td><td>运动中的关键硬件故障、连续丢帧、跟踪误差、碰撞停止</td><td>回调只记录并通知；控制接口返回后由任务层统一处理</td></tr><tr><td>限幅、提前返回或日志</td><td>目标越界、速度/力矩过大、碰撞检测主动停止</td><td>同时检查返回后的状态、日志和回调，不要只依赖异常</td></tr></tbody></table><p><code>on_error</code> 在控制/反馈路径中同步调用。SDK 会吞掉回调本身抛出的异常，因此回调中不应执行耗时 I/O、等待锁或再次调用机械臂控制接口。推荐在回调中保存错误并设置 <code>threading.Event</code>，等当前控制接口返回后再处理。</p><h3 id="sdk-异常类型和诊断字段" tabindex="-1">SDK 异常类型和诊断字段 <a class="header-anchor" href="#sdk-异常类型和诊断字段" aria-label="Permalink to &quot;SDK 异常类型和诊断字段&quot;">​</a></h3><p>除特别说明外，下列类型都继承自 <code>OneroError</code>：</p><table tabindex="0"><thead><tr><th>异常</th><th>诊断字段</th><th>当前源码中的用途</th></tr></thead><tbody><tr><td><code>OneroConnectionError</code></td><td><code>channel</code>、<code>detail</code></td><td>创建 CAN 通道或后端时接口不可用</td></tr><tr><td><code>OneroHardwareError</code></td><td><code>joint_index</code>、<code>error_code</code>、<code>description</code></td><td>电机故障、使能失败，以及安全监控合成的停机错误</td></tr><tr><td><code>OneroConfigError</code></td><td><code>detail</code></td><td>型号、构造参数、控制参数、坐标/工具/负载配置不合法</td></tr><tr><td><code>OneroTimeoutError</code></td><td><code>joint_index</code>、<code>missed_frames</code>、<code>detail</code></td><td>已公开但当前生产路径没有直接抛出；连续丢帧通过 <code>on_error</code> 交付 <code>OneroHardwareError</code></td></tr><tr><td><code>OneroSafetyError</code></td><td><code>reason</code>、<code>joint_index</code></td><td>当前用于笛卡尔轨迹关节跳变和笛卡尔速度奇异点硬阈值</td></tr><tr><td><code>IKConvergenceError</code></td><td><code>pos_err</code>、<code>rot_err</code>、<code>iters</code>、<code>pos_tol</code>、<code>rot_tol</code>、<code>q</code>、<code>target_pos</code></td><td><code>movel()</code>、<code>movep()</code>、<code>movec()</code>、<code>servop()</code> 的严格逆解不收敛</td></tr></tbody></table><p><code>IKConvergenceError</code> 当前没有从包根导出，需要这样导入：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> onero_sdk.exceptions </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IKConvergenceError</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>joint_index</code> 是从 0 开始的源码索引：<code>0</code> 对应 J1，<code>6</code> 对应 J7。<code>-1</code> 表示整机或无法归属某一关节。<code>OneroSafetyError</code> 的文本会显示 <code>joint_index + 1</code>，但字段本身仍是从 0 开始。</p><h3 id="公开接口与异常对照" tabindex="-1">公开接口与异常对照 <a class="header-anchor" href="#公开接口与异常对照" aria-label="Permalink to &quot;公开接口与异常对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口或功能</th><th>直接抛出的主要异常</th><th>还需要检查的回调或行为</th></tr></thead><tbody><tr><td><code>Arm(...)</code></td><td><code>OneroConfigError</code>、<code>OneroConnectionError</code></td><td>后续裸 CAN 发送失败不保证全部包装成 SDK 异常</td></tr><tr><td><code>enable()</code></td><td><code>OneroHardwareError</code>；末端执行器可能抛 <code>RuntimeError</code></td><td>任一电机使能失败时不会进入可运动状态</td></tr><tr><td><code>movej()</code>、<code>home()</code></td><td><code>OneroError</code>、<code>OneroConfigError</code></td><td>目标关节越界会限幅并记录警告；运动中的硬件故障通过 <code>on_error</code></td></tr><tr><td><code>movel()</code>、<code>movec()</code></td><td><code>OneroError</code>、<code>OneroConfigError</code>，另有 <code>IKConvergenceError</code>、轨迹关节跳变 <code>OneroSafetyError</code></td><td>碰撞停止或硬件停机可能提前结束运动而不是从调用点抛出</td></tr><tr><td><code>movep()</code></td><td><code>OneroError</code>、<code>OneroConfigError</code>，另有 <code>IKConvergenceError</code></td><td>先严格求解目标位姿，再执行关节空间插补</td></tr><tr><td><code>servoj()</code></td><td><code>OneroError</code>、<code>OneroConfigError</code></td><td>位置、速度和力矩由安全后端限幅</td></tr><tr><td><code>servop()</code></td><td>上述异常，另有 <code>IKConvergenceError</code></td><td>控制循环中仍要处理 <code>on_error</code></td></tr><tr><td><code>speedj()</code></td><td><code>OneroError</code>、<code>OneroConfigError</code></td><td>超过关节速度上限时限幅，不抛速度异常</td></tr><tr><td><code>speedl()</code></td><td>上述异常，另有奇异点 <code>OneroSafetyError</code></td><td>笛卡尔速度会转换并限幅到安全关节速度</td></tr><tr><td><code>force_mode()</code></td><td><code>OneroError</code>、<code>OneroConfigError</code></td><td>主动接触不等于碰撞错误；需自行制定退出条件</td></tr><tr><td><code>freedrive_enable()</code></td><td>参数/依赖问题为 <code>OneroConfigError</code></td><td>后台示教循环异常会紧急停止，并通过 <code>on_error</code> 交付</td></tr><tr><td><code>CollisionConfig(...)</code>、<code>enable_collision_detection()</code></td><td>配置构造可能抛 <code>TypeError</code>、<code>ValueError</code>；未使能时为 <code>OneroError</code></td><td>检测结果通过 <code>on_collision</code>、<code>last_collision</code> 和停止时的 <code>on_error</code> 交付</td></tr><tr><td><code>get_state()</code> / <code>arm.state</code></td><td>底层异常可能直接上抛</td><td>高层 <code>ArmState</code> 不含电机错误码和温度，不能用它判定超载；缺帧时可能沿用上次状态</td></tr><tr><td><code>emergency_stop()</code></td><td>通常不抛出</td><td>直接失能并设置急停标志，但不会调用 <code>on_error</code>；后续控制命令会抛 <code>OneroError</code></td></tr><tr><td><code>stop()</code></td><td><code>OneroError</code> 或安全后端的 <code>OneroHardwareError</code></td><td>是受控减速，不等于急停或失能</td></tr><tr><td><code>disable()</code></td><td>后端异常</td><td>撤销保持力矩；机械臂未可靠支撑时不得调用</td></tr><tr><td><code>DualArm.enable()</code></td><td>重新抛出单臂异常；并行双侧同时失败时为 <code>OneroError</code></td><td>第二条机械臂使能失败时会尝试失能第一条机械臂</td></tr></tbody></table><p>参数和调用状态决定具体异常。调用方应从最具体的类型捕获到 <code>OneroError</code>，不能只按接口名假定一种异常。</p><h3 id="电机状态与故障码" tabindex="-1">电机状态与故障码 <a class="header-anchor" href="#电机状态与故障码" aria-label="Permalink to &quot;电机状态与故障码&quot;">​</a></h3><p>电机反馈首字节的高 4 位是 <code>MotorError</code>。<code>0x0</code> 和 <code>0x1</code> 是正常状态，其余是电机固件报告的故障：</p><table tabindex="0"><thead><tr><th style="text-align:right;">十六进制</th><th>枚举</th><th>含义</th><th><code>enable()</code> 前已锁存</th><th>运行中的当前处理</th></tr></thead><tbody><tr><td style="text-align:right;"><code>0x0</code></td><td><code>DISABLED</code></td><td>电机失能，正常状态</td><td>可进入使能流程</td><td>非故障</td></tr><tr><td style="text-align:right;"><code>0x1</code></td><td><code>ENABLED</code></td><td>电机已使能，正常状态</td><td>可接受为已使能</td><td>非故障</td></tr><tr><td style="text-align:right;"><code>0x8</code></td><td><code>OVERVOLTAGE</code></td><td>过压</td><td>直接抛 <code>OneroHardwareError</code>，保留 <code>0x8</code></td><td>紧急停止并调用 <code>on_error</code></td></tr><tr><td style="text-align:right;"><code>0x9</code></td><td><code>UNDERVOLTAGE</code></td><td>欠压</td><td>直接抛出，保留 <code>0x9</code></td><td>当前不会触发关键故障回调，应结合供电和 CAN 日志排查</td></tr><tr><td style="text-align:right;"><code>0xA</code></td><td><code>OVERCURRENT</code></td><td>过流</td><td>直接抛出，保留 <code>0xA</code></td><td>紧急停止并调用 <code>on_error</code></td></tr><tr><td style="text-align:right;"><code>0xB</code></td><td><code>MOSFET_OVERTEMP</code></td><td>MOSFET 过温</td><td>直接抛出，保留 <code>0xB</code></td><td>紧急停止并调用 <code>on_error</code></td></tr><tr><td style="text-align:right;"><code>0xC</code></td><td><code>COIL_OVERTEMP</code></td><td>线圈过温</td><td>直接抛出，保留 <code>0xC</code></td><td>紧急停止并调用 <code>on_error</code></td></tr><tr><td style="text-align:right;"><code>0xD</code></td><td><code>COMM_LOSS</code></td><td>电机通信丢失</td><td>直接抛出，保留 <code>0xD</code></td><td>当前记录警告；连续命令反馈丢失由超时监控停机</td></tr><tr><td style="text-align:right;"><code>0xE</code></td><td><code>OVERLOAD</code></td><td>电机过载/超载</td><td>直接抛出，保留 <code>0xE</code></td><td>紧急停止并调用 <code>on_error</code></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">不能只看运行期回调的 <code>error_code</code></p><p>安全监控触发紧急停止时会新建一个 <code>OneroHardwareError</code>，当前实现把其 <code>error_code</code> 统一设为 <code>0</code>，并把原始故障名写进 <code>description</code>。因此，运行期的超载回调必须同时检查 <code>description</code> 中的 <code>OVERLOAD</code>。<code>0</code> 在这里是 SDK 合成错误码，不应解释为电机的 <code>DISABLED</code> 状态。</p></div><h3 id="安全监控中不会直接抛异常的情况" tabindex="-1">安全监控中不会直接抛异常的情况 <a class="header-anchor" href="#安全监控中不会直接抛异常的情况" aria-label="Permalink to &quot;安全监控中不会直接抛异常的情况&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>默认阈值或配置</th><th>当前行为</th></tr></thead><tbody><tr><td>单帧关节增量过大</td><td><code>max_delta_per_step=0.03 rad</code></td><td>对命令限幅</td></tr><tr><td>关节速度过大</td><td><code>max_velocity=6 rad/s</code>，且不超过型号关节限制</td><td>对命令限幅</td></tr><tr><td>目标超出关节位置限制</td><td>型号 <code>JointSpec</code> 限制</td><td>限幅并记录警告</td></tr><tr><td>力矩命令过大</td><td>型号力矩限制</td><td>对命令限幅</td></tr><tr><td>连续命令反馈丢失</td><td><code>timeout_frames=10</code></td><td>紧急停止；<code>on_error</code> 收到 <code>OneroHardwareError(code=0)</code>，不是 <code>OneroTimeoutError</code></td></tr><tr><td>硬跟踪误差</td><td><code>1.0 rad</code> 持续 10 帧</td><td>紧急停止并调用 <code>on_error</code></td></tr><tr><td>软跟踪误差</td><td><code>0.5 rad</code> 持续 100 帧</td><td>紧急停止并调用 <code>on_error</code></td></tr><tr><td>手动 <code>emergency_stop()</code></td><td>调用即触发</td><td>失能并设置急停状态，不调用 <code>on_error</code></td></tr></tbody></table><p>这些默认值来自 <code>SafetyConfig</code>。如果项目覆盖了配置，应在错误日志中一并记录实际配置。</p><h3 id="碰撞检测的异常和回调" tabindex="-1">碰撞检测的异常和回调 <a class="header-anchor" href="#碰撞检测的异常和回调" aria-label="Permalink to &quot;碰撞检测的异常和回调&quot;">​</a></h3><p><code>enable_collision_detection(config, on_collision)</code> 作用于 <code>movej()</code>、<code>movel()</code>、<code>movep()</code>、<code>movec()</code>、<code>speedj()</code> 和 <code>speedl()</code> 的计划运动，不作用于 <code>servoj()</code>、<code>servop()</code> 或 <code>force_mode()</code>。</p><p>检测到碰撞后：</p><ul><li>只要注册了 <code>on_collision(event)</code>，当前实现检测到事件后都会调用它；<code>event</code> 字段包括 <code>timestamp</code>、<code>channel</code>、<code>joint_index</code>、<code>magnitude</code>、<code>threshold</code>、<code>torques</code>、<code>velocities</code>、<code>joints</code>，并可读取 <code>severity</code>。</li><li><code>CollisionResponse.STOP</code> 会执行安全停止；当前实现仍会调用已经注册的碰撞回调。</li><li><code>CollisionResponse.CALLBACK</code> 只调用碰撞回调，不自动停止。</li><li><code>CollisionResponse.BOTH</code> 同时回调并停止。</li><li>选择停止时，运动接口可能提前返回，而不是直接抛出异常；<code>on_error</code> 还会收到 <code>OneroHardwareError(code=0)</code>。</li><li>SDK 会吞掉 <code>on_collision</code> 回调自身抛出的异常；回调同样应保持短小。</li><li><code>arm.last_collision</code> 可读取最近一次碰撞事件。</li></ul><p>不要把 <code>OneroSafetyError</code> 当作碰撞检测的通用异常。当前源码中的碰撞交付入口是 <code>on_collision</code>、<code>last_collision</code> 和停止时的 <code>on_error</code>。</p><h3 id="末端执行器和底层异常" tabindex="-1">末端执行器和底层异常 <a class="header-anchor" href="#末端执行器和底层异常" aria-label="Permalink to &quot;末端执行器和底层异常&quot;">​</a></h3><p>并非所有可见错误都继承自 <code>OneroError</code>。夹爪、灵巧手和部分底层 CAN/协议接口还可能抛出：</p><table tabindex="0"><thead><tr><th>Python 内置异常</th><th>常见原因</th></tr></thead><tbody><tr><td><code>TypeError</code></td><td>碰撞响应枚举、回调对象或底层对象类型不合法</td></tr><tr><td><code>ValueError</code></td><td>参数范围、帧长度或协议数据不合法</td></tr><tr><td><code>RuntimeError</code></td><td>末端执行器未启用、无反馈、状态错误或底层运行失败</td></tr><tr><td><code>NotImplementedError</code></td><td>当前末端执行器不支持所调用功能</td></tr><tr><td><code>ImportError</code></td><td>缺少可选 CAN 或运动学依赖</td></tr></tbody></table><p>因此，硬件应用若使用末端执行器或底层接口，不能只捕获 <code>OneroError</code>。仍应优先捕获具体异常，并在最后单独记录这些内置异常。</p><h3 id="推荐处理顺序" tabindex="-1">推荐处理顺序 <a class="header-anchor" href="#推荐处理顺序" aria-label="Permalink to &quot;推荐处理顺序&quot;">​</a></h3><ol><li>在 <code>Arm</code> 构造函数中注册 <code>on_error</code>，在碰撞检测中注册 <code>on_collision</code>。</li><li>按 <code>OneroConnectionError</code>、<code>OneroHardwareError</code>、<code>IKConvergenceError</code>、<code>OneroSafetyError</code>、<code>OneroConfigError</code>、<code>OneroTimeoutError</code>、<code>OneroError</code> 的顺序捕获。</li><li>回调只复制异常字段、保存现场状态并通知任务层，不在回调里重试、停止或重新使能。</li><li>控制接口返回后检查回调标志。若安全监控已紧急停止，不要再把 <code>stop()</code> 当作恢复动作重复发送。</li><li>保存 <code>joint_index</code>、<code>error_code</code>、<code>description</code>、时间戳、运动目标、实际状态、工具/负载配置和 CAN 日志。</li><li>确认机械和电气原因已经排除后，从低速、小幅动作重新验证。</li></ol><h2 id="停止与失能" tabindex="-1">停止与失能 <a class="header-anchor" href="#停止与失能" aria-label="Permalink to &quot;停止与失能&quot;">​</a></h2><p>优先使用 <code>arm.stop(deceleration=...)</code> 中止常规运动。<code>disable()</code> 会撤销电机力矩，只应在机械臂得到可靠支撑后执行。现场紧急情况应优先切断 DC 48 V 供电。</p><h3 id="停止、失能与关闭动作对照" tabindex="-1">停止、失能与关闭动作对照 <a class="header-anchor" href="#停止、失能与关闭动作对照" aria-label="Permalink to &quot;停止、失能与关闭动作对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景或用途</th><th>优先动作</th><th style="text-align:right;">是否停止当前运动</th><th style="text-align:right;">是否撤销保持力矩</th><th style="text-align:right;">是否释放通信资源</th><th>后续处理</th></tr></thead><tbody><tr><td>常规任务中止</td><td><code>stop()</code></td><td style="text-align:right;">是</td><td style="text-align:right;">否</td><td style="text-align:right;">否</td><td>读取状态，确认已停稳</td></tr><tr><td>通信或软件异常</td><td><code>stop()</code>，必要时切断供电</td><td style="text-align:right;">是</td><td style="text-align:right;">默认否</td><td style="text-align:right;">否</td><td>保留异常日志并排查 CAN</td></tr><tr><td>人员进入区域、即将碰撞等紧急危险</td><td>现场急停、<code>emergency_stop()</code> 或切断 DC 48 V 供电</td><td style="text-align:right;">紧急中止</td><td style="text-align:right;">是</td><td style="text-align:right;">取决于后续关闭</td><td>先确保人员和设备安全，再分析原因</td></tr><tr><td>已可靠支撑，需要撤销保持力矩</td><td><code>disable()</code></td><td style="text-align:right;">是</td><td style="text-align:right;">是</td><td style="text-align:right;">否</td><td>确认机械臂不会因失能下落</td></tr><tr><td>只释放 SDK/总线资源</td><td><code>close()</code></td><td style="text-align:right;">不作为停止流程使用</td><td style="text-align:right;">默认否</td><td style="text-align:right;">是</td><td>关闭前单独处理机械臂运动状态</td></tr><tr><td>已可靠支撑并结束会话</td><td><code>close(disable=True)</code></td><td style="text-align:right;">结束时失能</td><td style="text-align:right;">是</td><td style="text-align:right;">是</td><td>确认支撑条件持续有效</td></tr></tbody></table><p>程序退出、浏览器关闭和网络断开都不是现场安全动作。应用应把运动中止、失能和资源释放明确写在不同的分支中，并在异常路径中先处理机械臂状态。</p><p>完整示例：<a href="/onerobot-A1/use-cases/basic-safety#安全停止">安全停止</a>。</p><p><code>stop()</code>、<code>disable()</code>、<code>close()</code> 和紧急停止的含义不同，不能互相替代。</p><h2 id="异常后的恢复顺序" tabindex="-1">异常后的恢复顺序 <a class="header-anchor" href="#异常后的恢复顺序" aria-label="Permalink to &quot;异常后的恢复顺序&quot;">​</a></h2><p>异常后不要立即重试，也并非所有异常都需要断电。参数或逆解错误通常只需修正输入；可清除的电机故障在排除原因后可尝试软件恢复：</p><ol><li>确认机械臂已经停稳，人员、工具和工件处于安全状态。</li><li>保存异常、运动目标、关节反馈和 CAN 状态，并排除故障原因。</li><li>可靠支撑机械臂后调用 <code>disable()</code>，失能操作会撤销保持力矩。</li><li>调用 <code>enable()</code>。全部关节均已失能时，SDK 会发送清错指令、尝试重新使能，并复位 SDK 的紧急停止状态；SDK 没有单独的公开清错方法。</li><li>读取状态，先仿真验证，再进行低速、小幅真机复测。不要直接续跑原任务。</li></ol><p>现场急停未复位、故障原因不明、温度或供电未恢复、机械结构仍卡滞、CAN 反馈不稳定，或故障再次出现时，应保持停止并断电检查。不要在 <code>on_error</code> 回调中恢复或自动循环重试。</p><table tabindex="0"><thead><tr><th>已观察到的问题</th><th>优先保留的信息</th></tr></thead><tbody><tr><td>目标没有按预期到达</td><td>目标值、<code>duration</code>、实际关节角/位姿、负载和速度参数</td></tr><tr><td>通信超时或无反馈</td><td>CAN 接口详情、统计信息、<code>candump</code> 片段和供电状态</td></tr><tr><td>笛卡尔方向错误</td><td><code>frame</code>、<code>mounting</code>、世界坐标、TCP 和当前位姿</td></tr><tr><td>接触或力控异常</td><td>接触面、<code>selection</code>、<code>wrench</code>、参考坐标系和停止时反馈</td></tr></tbody></table><p>保留这些信息可以避免通过反复发送更激进的目标来“试出结果”。</p>`,51)])])}const E=e(c,[["render",a]]);export{g as __pageData,E as default};
